package com.jobtrack.controller;
import com.jobtrack.model.*;import com.jobtrack.service.JobApplicationService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.util.NoSuchElementException;
@Controller @RequestMapping("/applications") public class ApplicationController {
 private final JobApplicationService service;public ApplicationController(JobApplicationService s){service=s;}
 @ModelAttribute("statuses") public ApplicationStatus[] statuses(){return ApplicationStatus.values();}
 @GetMapping public String list(Authentication a,Model m,@RequestParam(required=false)String q,@RequestParam(required=false)ApplicationStatus status){var list=service.all(a.getName());if(q!=null&&!q.isBlank())list=list.stream().filter(x->x.getJobTitle().toLowerCase().contains(q.toLowerCase())||x.getCompany().toLowerCase().contains(q.toLowerCase())).toList();if(status!=null)list=list.stream().filter(x->x.getStatus()==status).toList();m.addAttribute("applications",list);m.addAttribute("q",q);m.addAttribute("selectedStatus",status);return "applications/list";}
 @GetMapping("/new") public String create(Model m){m.addAttribute("application",new JobApplication());return "applications/form";}
 @PostMapping public String save(@Valid @ModelAttribute("application")JobApplication app,BindingResult result,Authentication a){if(result.hasErrors())return "applications/form";service.save(app,a.getName());return "redirect:/applications?created";}
 @GetMapping("/{id}") public String detail(@PathVariable Long id,Authentication a,Model m){m.addAttribute("application",service.get(id,a.getName()));return "applications/detail";}
 @GetMapping("/{id}/edit") public String edit(@PathVariable Long id,Authentication a,Model m){m.addAttribute("application",service.get(id,a.getName()));return "applications/form";}
 @PostMapping("/{id}") public String update(@PathVariable Long id,@Valid @ModelAttribute("application")JobApplication form,BindingResult result,Authentication a){if(result.hasErrors())return "applications/form";JobApplication old=service.get(id,a.getName());old.setJobTitle(form.getJobTitle());old.setCompany(form.getCompany());old.setLocation(form.getLocation());old.setJobUrl(form.getJobUrl());old.setStatus(form.getStatus());old.setAppliedDate(form.getAppliedDate());old.setInterviewDate(form.getInterviewDate());old.setNotes(form.getNotes());service.save(old,a.getName());return "redirect:/applications/"+id;}
 @PostMapping("/{id}/delete") public String delete(@PathVariable Long id,Authentication a){service.delete(id,a.getName());return "redirect:/applications?deleted";}
}
